import React, { useState, useEffect } from 'react';
import MapDisplay from './MapDisplay';
import './App.css';

function App() {
  const [customers, setCustomers] = useState([]);
  const [storages, setStorages] = useState([]);
  const [selectedStorageId, setSelectedStorageId] = useState(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [dailyCustomerCount, setDailyCustomerCount] = useState(0);
  const [numTrucks, setNumTrucks] = useState(0);
  const [productWeight, setProductWeight] = useState(0);
  const [optimizationResult, setOptimizationResult] = useState(null);
  const [selectedCustomerIds, setSelectedCustomerIds] = useState([]);

  // Default map center set to central Saigon (District 1)
  const defaultCenter = [10.776889, 106.700806];

  // Fetch dynamic customer data from the backend.
  useEffect(() => {
    fetch("http://127.0.0.1:5000/customers")
      .then(response => response.json())
      .then(data => setCustomers(data.customers))
      .catch(err => console.error("Error fetching customers:", err));
  }, []);

  // Fetch storage data from the backend.
  useEffect(() => {
    fetch("http://127.0.0.1:5000/storages")
      .then(response => response.json())
      .then(data => {
        setStorages(data.storages);
        if (data.storages && data.storages.length > 0) {
          setSelectedStorageId(data.storages[0].StorageID);
        }
      })
      .catch(err => console.error("Error fetching storages:", err));
  }, []);

  // Toggle selection for a customer
  const handleCustomerToggle = (customerId) => {
    setSelectedCustomerIds(prev => 
      prev.includes(customerId)
        ? prev.filter(id => id !== customerId)
        : [...prev, customerId]
    );
  };

  // Filter customers based on the search term.
  const filteredCustomers = customers.filter(customer =>
    customer.CustomerName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    customer.CustomerAddress.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Handle optimization submission.
  const handleSubmit = async () => {
    const selectedCustomers = customers.filter(c => selectedCustomerIds.includes(c.CustomerID));
    const customerLocations = selectedCustomers.map(c => c.location);
    const selectedStorage = storages.find(s => s.StorageID === selectedStorageId);

    const payload = {
      locations: customerLocations,
      num_vehicles: numTrucks,
      depot: selectedStorage ? selectedStorage.location : defaultCenter,
      storage_address: selectedStorage ? selectedStorage.StorageAddress : '',
      daily_customers: dailyCustomerCount,
      total_weight: productWeight
    };

    try {
      const res = await fetch("http://127.0.0.1:5000/optimize", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      });
      const jsonData = await res.json();
      setOptimizationResult(jsonData);
    } catch (error) {
      console.error("Error optimizing routes:", error);
    }
  };

  const mapCenter = storages.find(s => s.StorageID === selectedStorageId)?.location || defaultCenter;

  return (
    <div className="container">
      <header className="header">
        <div className="header-left">
          <h1 className="route-name">Delivery Optimizer</h1>
          <p className="route-desc">Your daily route optimization solution</p>
        </div>
        <div className="header-right">
          <button className="btn new-route">+ Create new route</button>
        </div>
      </header>

      <div className="content">
        <aside className="sidebar">
          <div className="sidebar-header">
            <h2>
              {new Date().toLocaleDateString("en-US", { weekday: "long", month: "short", day: "numeric" })}
            </h2>
            <button className="btn manage-drivers">Manage Drivers</button>
          </div>

          <div className="stops-section">
            <h3>Stops</h3>
            <input
              type="text"
              className="search-input"
              placeholder="Search customers..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
            <div className="customer-list">
              {filteredCustomers.length === 0 ? (
                <p>No stops available</p>
              ) : (
                filteredCustomers.map(customer => (
                  <div
                    key={customer.CustomerID}
                    onClick={() => handleCustomerToggle(customer.CustomerID)}
                    className={`customer-item ${selectedCustomerIds.includes(customer.CustomerID) ? 'selected' : ''}`}
                  >
                    <strong>{customer.CustomerName}</strong>
                    <p>{customer.CustomerAddress}</p>
                  </div>
                ))
              )}
            </div>
          </div>
        </aside>

        <main className="main-area">
          <div className="form-section">
            <div className="input-group">
              <label>Daily Customer Count:</label>
              <input
                type="number"
                min="0"
                value={dailyCustomerCount}
                onChange={(e) => setDailyCustomerCount(Number(e.target.value))}
                className="number-input"
              />
            </div>
            <div className="input-group">
              <label>Select Storage:</label>
              <select
                value={selectedStorageId || ''}
                onChange={(e) => setSelectedStorageId(Number(e.target.value))}
                className="select-input"
              >
                {storages.map(storage => (
                  <option key={storage.StorageID} value={storage.StorageID}>
                    {storage.StorageName} - {storage.StorageAddress}
                  </option>
                ))}
              </select>
            </div>
            <div className="input-group">
              <label>Truck & Product Details:</label>
              <div className="detail-group">
                <span>Trucks Needed:</span>
                <input
                  type="number"
                  min="0"
                  value={numTrucks}
                  onChange={(e) => setNumTrucks(Number(e.target.value))}
                  className="number-input"
                />
              </div>
              <div className="detail-group">
                <span>Product Weight (kg):</span>
                <input
                  type="number"
                  min="0"
                  value={productWeight}
                  onChange={(e) => setProductWeight(Number(e.target.value))}
                  className="number-input"
                />
              </div>
            </div>
            <button onClick={handleSubmit} className="btn optimize-btn">
              Submit for Optimized Route
            </button>
          </div>

          <div className="map-container">
            <MapDisplay defaultCenter={mapCenter} zoom={13} />
          </div>
        </main>
      </div>

      {optimizationResult && (
        <div className="result-container">
          <h2>Optimization Result</h2>
          <pre className="result-output">
            {JSON.stringify(optimizationResult, null, 2)}
          </pre>
        </div>
      )}
    </div>
  );
}

export default App;
